/** 정육면체 겨냥도 — 앞면의 왼쪽 위 (x, y), 모서리 s, 깊이 d. 가려진 모서리는 점선. */
const cube = (x: number, y: number, s: number, d: number) =>
  poly(`${x},${y} ${x + d},${y - d} ${x + d + s},${y - d} ${x + s},${y}`) +
  poly(
    `${x + s},${y} ${x + d + s},${y - d} ${x + d + s},${y - d + s} ${x + s},${y + s}`,
  ) +
  poly(`${x},${y} ${x + s},${y} ${x + s},${y + s} ${x},${y + s}`) +
  path(
    `M${x} ${y + s}L${x + d} ${y + s - d}V${y - d}M${x + d} ${y + s - d}H${x + d + s}`,
    DASH,
  );

